(()=>{if(location.pathname.startsWith('/cms'))return;const SB='https://xleceiffuopioeguniwj.supabase.co/rest/v1/rentcam_reviews',KEY='sb_publishable_POksYryhG_mkFbs7N0fjKQ_4dUim7Ex',esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let cache=[];
 function cards(){return cache.map(r=>`<article class="rc-review-card"><b>${esc(r.name)}</b><span aria-label="${r.rating} dari 5 bintang">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</span><p>${esc(r.message)}</p></article>`).join('')}
 function menu(){const nav=document.querySelector('#drawer .rc-drawer-nav')||document.querySelector('#drawer');if(nav&&!nav.querySelector('[data-customer-reviews]'))nav.insertAdjacentHTML('beforeend','<button type="button" class="drawer-link" data-customer-reviews><span class="drawer-link-icon"><svg viewBox="0 0 24 24"><path d="M4 4h16v12H9l-5 4V4Z"/><path d="m12 6 1.2 2.5 2.8.4-2 2 .5 2.8-2.5-1.3-2.5 1.3.5-2.8-2-2 2.8-.4Z"/></svg></span><span><b>Masukan & Ulasan</b><small>Ceritakan pengalaman rental Anda</small></span></button>');const app=document.getElementById('app');if(location.pathname==='/'&&cache.length&&app&&!app.querySelector('#rcPublishedReviews'))app.insertAdjacentHTML('beforeend','<section id="rcPublishedReviews" class="container"><h2>Ulasan Pelanggan</h2><div class="rc-review-grid">'+cards()+'</div></section>')}
 function open(){if(document.querySelector('#rcReviewDialog'))return;document.getElementById('drawer')?.classList.remove('open');const dialog=document.createElement('dialog');dialog.id='rcReviewDialog';dialog.innerHTML=`<div class="rc-review-heading"><div><h2>Masukan & Ulasan</h2><p>Bagikan pengalaman Anda tentang rental ini.</p></div><button type="button" data-review-close aria-label="Tutup">×</button></div><form><label>Jenis kiriman<select name="kind"><option value="review">Ulasan rental</option><option value="feedback">Masukan untuk rental</option></select></label><label>Nama<input name="name" required minlength="2" maxlength="100" autocomplete="name"></label><fieldset class="rc-review-stars"><legend>Penilaian Anda</legend>${[1,2,3,4,5].map(n=>`<label><input type="radio" name="rating" value="${n}" required><span aria-hidden="true">★</span><small>${n}</small></label>`).join('')}</fieldset><label>Cerita / masukan<textarea name="message" required minlength="5" maxlength="2000" rows="5" placeholder="Bagaimana pengalaman Anda menyewa di sini?"></textarea></label><small>Kiriman masuk ke CMS. Admin menentukan apakah ulasan ditampilkan di website.</small><p role="status" data-review-status></p><button class="btn" type="submit">Kirim</button></form>${cache.length?'<h3>Ulasan Pelanggan</h3><div class="rc-review-grid">'+cards()+'</div>':''}`;document.body.append(dialog);const f=dialog.querySelector('form');dialog.querySelector('[data-review-close]').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove());f.elements.kind.onchange=()=>{const review=f.elements.kind.value==='review';f.querySelector('fieldset').hidden=!review;f.querySelectorAll('[name=rating]').forEach(x=>x.required=review)};f.addEventListener('change',()=>{const rating=Number(f.elements.rating.value);f.querySelectorAll('.rc-review-stars label').forEach((l,i)=>l.dataset.active=i<rating?'true':'false')});f.onsubmit=async e=>{e.preventDefault();if(!f.reportValidity())return;const button=f.querySelector('[type=submit]'),status=f.querySelector('[data-review-status]');button.disabled=true;try{const r=await fetch(SB,{method:'POST',headers:{apikey:KEY,'Content-Type':'application/json',Prefer:'return=minimal'},body:JSON.stringify({kind:f.elements.kind.value,name:f.elements.name.value.trim(),rating:f.elements.kind.value==='review'?Number(f.elements.rating.value):null,message:f.elements.message.value.trim(),published:false})});if(!r.ok)throw Error('Kiriman belum berhasil disimpan. Coba kembali.');f.reset();status.textContent='Terima kasih. Kiriman Anda sudah masuk ke CMS untuk ditinjau.';}catch(e){status.textContent=e.message}finally{button.disabled=false}};dialog.showModal()}
 document.addEventListener('click',e=>{if(e.target.closest('[data-customer-reviews]')){e.preventDefault();open()}},true);new MutationObserver(menu).observe(document.getElementById('app'),{childList:true,subtree:true});const d=document.getElementById('drawer');if(d)new MutationObserver(menu).observe(d,{childList:true,subtree:true});fetch(SB+'?select=name,rating,message&kind=eq.review&published=eq.true&order=created_at.desc&limit=30',{headers:{apikey:KEY}}).then(r=>r.ok?r.json():[]).then(rows=>{cache=rows;menu()}).catch(()=>{});menu();
})();
